import { AUDIENCE_PLANNING_BFF_COMPONENT_IDS } from '../../../../../constants';
import type { InteractiveAudienceType } from '../../../types';
import { getField, isRecord } from './bffFieldAccess';
import {
  canonicalAudienceCardTitle,
  extractBrandAudienceCardsFromBff,
} from './definitionBrandAudienceBff';

const CARD_TITLE_BY_AUDIENCE: Record<InteractiveAudienceType, string> = {
  core: 'Core Audience',
  halo: 'Halo Audience',
};

const normalizeBrandVolumeValue = (value: unknown): string | null => {
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  if (typeof value === 'string' && value.trim() !== '') {
    return value.trim().replace(/%$/, '');
  }
  return null;
};

const readBrandVolumeValue = (rows: unknown): string | null => {
  if (!Array.isArray(rows)) return null;

  for (const row of rows) {
    if (!isRecord(row)) continue;
    const brandVolume = getField(
      row,
      'brandVolume',
      'brand_volume',
      'BrandVolume',
    );
    if (!isRecord(brandVolume)) continue;

    const value = normalizeBrandVolumeValue(
      getField(brandVolume, 'value', 'percentage', 'pct'),
    );
    if (value !== null) return value;
  }

  return null;
};

/**
 * Dynamic-UX shape: the `audience-cards` component exposes a single top-level
 * `brandVolume` already computed for the requested audience, e.g.
 * `{ cards: [...], brandVolume: { value: '100.0' } }`.
 */
const readTopLevelBrandVolume = (data: unknown): string | null => {
  if (!isRecord(data)) return null;

  const audienceCards = getField(
    data,
    AUDIENCE_PLANNING_BFF_COMPONENT_IDS.DEFINITION_AUDIENCE_CARDS,
    'audience-cards',
    'audienceCards',
    'audience_cards',
  );
  const container = isRecord(audienceCards) ? audienceCards : data;

  const brandVolume = getField(
    container,
    'brandVolume',
    'brand_volume',
    'BrandVolume',
  );
  if (!isRecord(brandVolume)) return null;

  return normalizeBrandVolumeValue(
    getField(brandVolume, 'value', 'percentage', 'pct'),
  );
};

export const mapInteractiveAudienceResponse = (
  data: unknown,
  audienceType: InteractiveAudienceType,
): string | null => {
  const topLevelValue = readTopLevelBrandVolume(data);
  if (topLevelValue !== null) return topLevelValue;

  const cards = extractBrandAudienceCardsFromBff(data);
  if (!cards.length) return null;

  const wantedTitle = CARD_TITLE_BY_AUDIENCE[audienceType];
  const card =
    cards.find(
      (c) =>
        canonicalAudienceCardTitle(String(c.header?.title ?? '')) ===
        wantedTitle,
    ) ?? (cards.length === 1 ? cards[0] : undefined);

  if (!card) return null;

  return readBrandVolumeValue(card.data);
};
